s_cmp_eq_u32 s57, 2                                // ArgType == 2 ?
s_cbranch_scc0 label_SkipWaitForUserArgs           // skip wait if ArgType != 2
s_wait_kmcnt 0                                     // wait for 0/0 bytes of kern args
label_SkipWaitForUserArgs:  /// skip kern args wait if ArgType != 2

/* Early stop padded work-groups in a boundary cluster (grid rounded up to ClusterDim) */
s_cmp_ge_u32 s[sgprWorkGroup0], s[sgprNumWorkGroups0] // padded if WorkGroup0 >= tilesM
s_cbranch_scc1 label_ClusterPad_EarlyStop
s_and_b32 s56, s[sgprGSU], 0xfff                   // Restore GSU
s_mul_i32 s56, s[sgprNumWorkGroups1], s56          // tilesN * GSU
s_cmp_ge_u32 s[sgprWorkGroup1], s56                // padded if WorkGroup1 >= tilesN*GSU
s_cbranch_scc1 label_ClusterPad_EarlyStop
s_branch label_ClusterPad_NoEarlyStop
label_ClusterPad_EarlyStop:
