s_and_b32 s22, 255, s32                            // s22 = s32 % 256
s_addc_u32 s24, s24, 0
s_lshr_b32 s25, s33, 8                             // s25 = s33 / 256
s_and_b32 s22, 255, s33                            // s22 = s33 % 256
s_addc_u32 s25, s25, 0
s_mul_i32 s24, s24, s25
s_mul_i32 s24, s24, s34
s_and_b32 s25, s[sgprGSU], 0xfff                   // Restore GSU
s_mul_i32 s24, s24, s25
s_add_u32 s27, s27, s24
s_cmp_lt_u32 s[sgprWorkGroup0], s27
s_cbranch_scc1 label_FOUND
