s_load_b128 s[32:35], s[20:21], s26
s_add_u32 s18, s18, 1
s_cmp_lt_u32 s18, s55
s_cbranch_scc1 label_Loop_GemmCount

/* Grouped Gemm:: noLoadLoop */
label_wgTable_noLoadLoop:
s_wait_kmcnt 0
s_lshr_b32 s24, s32, 8                             // s24 = s32 / 256
s_and_b32 s22, 255, s32                            // s22 = s32 % 256
s_addc_u32 s24, s24, 0
s_lshr_b32 s25, s33, 8                             // s25 = s33 / 256
s_and_b32 s22, 255, s33                            // s22 = s33 % 256
s_addc_u32 s25, s25, 0
s_mul_i32 s24, s24, s25
s_mul_i32 s24, s24, s34
s_and_b32 s20, s[sgprGSU], 0xfff                   // Restore GSU
s_mul_i32 s24, s24, s20
s_add_u32 s27, s27, s24

/* Grouped Gemm:: gemmIndex found */
label_FOUND:
