s_lshr_b32 s[sgprNumWorkGroups0], s[sgprSizesFree+0], 8 // s[sgprNumWorkGroups0] = s[sgprSizesFree+0] / 256
s_and_b32 s57, 255, s[sgprSizesFree+0]             // s57 = s[sgprSizesFree+0] % 256
