v_add_nc_u32 v0, v0, v1                            // refine 2^32 / divisor
v_mul_hi_u32 v0, s[sgprWorkGroup0], v0             // s20 = s[sgprWorkGroup0] / s[sgprNumWorkGroups0]
v_mul_lo_u32 v1, v0, s[sgprNumWorkGroups0]         // s20 = s[sgprWorkGroup0] / s[sgprNumWorkGroups0]
v_sub_nc_u32 v1, s[sgprWorkGroup0], v1             // s20 = s[sgprWorkGroup0] / s[sgprNumWorkGroups0]
